//! 🎟️ Actual failed media command retirement returns the same native cause through one finite initiating caller.
use semio_framework_plugin_decl_app::ArtifactApp;
use semio_framework::FaultFrom;
use semio_framework_value::{FromValue, ToValue};
use semio_framework_plugin_reactor_app::PluginApp;
use crate::ops_ingress::{PluginCommandIngress, PluginCommandIngressStep};
use semio_framework_plugin_plugin_program::PluginProgram;
use semio_framework_value::retained_clone::{RetainedCloneGrant, RetainedCloneProgress};
use serde_json::Value;
use semio_framework_job::{OriginalJobFixtureCaller, OriginalTurnFailure};
use semio_framework_value::{ValueError, ValueRefusalKind};
use semio_framework_value::retirement::controlled::ControlledRetirement;
#[doc(hidden)]
pub fn clock()->Option<u64>{Some(1000)}
#[doc(hidden)]
pub fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn original_failed_media_decoded_source_same_cause_denials_and_full_paid_close(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let policy:serde_json::Value=serde_json::from_str(include_str!("../../../../../🧪️testing/🎟️caller/🧪️tests/🧫️fixtures/🎟️caller.json")).unwrap();let stock:RetainedCloneGrant=serde_json::from_value(policy["grant"].clone()).unwrap();
 for copy in [1,3,64]{let(mut caller,parent_heap)=observe(||OriginalJobFixtureCaller::admit(semio_framework_job::OperationId(policy["operation"].as_u64().unwrap()),semio_framework_job::Generation(policy["generation"].as_u64().unwrap()),stock,clock,policy["deadlineUs"].as_u64().unwrap(),policy["fuel"].as_u64().unwrap()));caller.turn(stock,|cx|{
  let((source,pointers),heap)=observe(||{let failure={let original=OriginalTurnFailure::from(ValueError::new(ValueRefusalKind::InvalidValue,law["failure"]["primary"].as_str().unwrap()));OriginalTurnFailure{receipt_refusal:Some(ValueError::new(ValueRefusalKind::OwnershipLimit,law["failure"]["receipt"].as_str().unwrap())),context_refusal:Some(ValueError::new(ValueRefusalKind::DepthLimit,law["failure"]["context"].as_str().unwrap())),..original}};let pointers=(failure.primary.message().as_ptr(),failure.receipt_refusal.as_ref().unwrap().message.as_ptr(),failure.context_refusal.as_ref().unwrap().message.as_ptr());let command=protocol::AppCommand::SubmitMediaExport{seq:law["command"]["seq"].as_str().unwrap().parse().unwrap(),port:law["command"]["port"].as_str().unwrap().into(),expected_parent_document_id:law["command"]["parent"].as_str().unwrap().into(),expected_base_revision:law["command"]["revision"].as_str().unwrap().parse().unwrap(),checkpoint_id:None};(PluginCommandIngress::FailedDecoded{owner:protocol::DecodedAppCommandOwner::new(command),failure:Some(failure),identity:(cx.operation(),cx.generation()),close_failure:None,compound:None,raw_media:None},pointers)});
  let(mut born,mut freed)=heap;cx.consume_retained(RetainedCloneProgress{copied_items:1,retained_capacity_bytes:born,..Default::default()})?;let mut source=Some(source);let mut output=None;let identity=(cx.operation(),cx.generation(),cx.deadline_us(),cx.clock_source()as usize,cx.original_recipient_identity());let loan=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,..stock};
  for turn in 0..policy["maximumTurns"].as_u64().unwrap(){let before=cx.retained_progress();let fuel=cx.fuel_remaining();let denied=RetainedCloneGrant{maximum_items:0,..loan};let(result,heap)=observe(||cx.with_retained_loan(denied,|same|{let next=source.take().unwrap().advance_original(1,same);let PluginCommandIngressStep::Pending(next)=next else{panic!("denied original source must remain pending")};source=Some(next);Ok(())}));result?;assert_eq!(heap,(0,0));assert_eq!(cx.retained_progress(),before);assert_eq!(cx.fuel_remaining(),fuel);
   let before=cx.retained_progress();let(result,heap)=observe(||cx.with_retained_loan(loan,|same|{match source.take().unwrap().advance_original(1,same){PluginCommandIngressStep::Pending(next)=>source=Some(next),PluginCommandIngressStep::TerminalOriginalFailure(failure)=>output=Some(failure),_=>panic!("media source cannot publish partial success")};Ok(())}));result?;let after=cx.retained_progress();let progress=RetainedCloneProgress{copied_items:after.copied_items-before.copied_items,copied_bytes:after.copied_bytes-before.copied_bytes,retained_capacity_bytes:after.retained_capacity_bytes-before.retained_capacity_bytes,released_bytes:after.released_bytes-before.released_bytes};assert!(progress.fits(loan));assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));born+=heap.0;freed+=heap.1;assert_eq!((cx.operation(),cx.generation(),cx.deadline_us(),cx.clock_source()as usize,cx.original_recipient_identity()),identity);if output.is_some(){break}assert!(turn+1<policy["maximumTurns"].as_u64().unwrap())}
  assert!(source.is_none());let failure=output.take().unwrap();assert_eq!((failure.primary.message().as_ptr(),failure.receipt_refusal.as_ref().unwrap().message.as_ptr(),failure.context_refusal.as_ref().unwrap().message.as_ptr()),pointers);let mut closing=ControlledRetirement::new(failure).unwrap_or_else(|_|panic!("complete original cause supports native retirement"));for turn in 0..policy["maximumTurns"].as_u64().unwrap(){if closing.terminal_is_empty(){break}let(result,heap)=observe(||cx.with_retained_loan(loan,|same|semio_framework_job::close_original_retained_step(same,closing.selected_demand(copy)?,|grant|closing.step(grant)).map(|step|step.progress())));let progress=result?;assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));born+=heap.0;freed+=heap.1;assert!(turn+1<policy["maximumTurns"].as_u64().unwrap())}assert!(closing.terminal_is_empty());assert_eq!(born,freed);assert_eq!(observe(||drop(closing)).1,(0,0));Ok(())}).unwrap();let(_,close)=observe(||caller.retire(stock));assert_eq!(parent_heap.0+close.0,parent_heap.1+close.1)}
}
